        "title": "Вопрос ба/бе",
        "meaning": "Вопрос, на который отвечают «да/нет», в этом уроке получает отдельную частицу ба или бе в конце.",
        "fullExplanation": "По норме курса одной вопросительной интонации недостаточно: Сен оқушысың? отмечено как ошибка, Сен оқушысың ба? — правильно. Частица пишется отдельно от предыдущего слова. В этом уроке упражнения специально подобраны так, чтобы использовать только ба/бе. Твёрдая форма получает ба, мягкая — бе: Сен доссың ба?, Сен дәрігерсің бе?. Полный выбор вопросительных частиц будет в 2-3.",
