        "meaning": "Сіздер — уважительное обращение к нескольким людям.",
        "fullExplanation": "К слову добавляется -сыздар после твёрдого слова или -сіздер после мягкого: Сіздер оқырмансыздар, Сіздер ақылдысыздар. Это множественный вариант уважительного сіз. Множественность уже видна в окончании, поэтому дополнительное множественное окончание на существительном в упражнениях не ставится. Не путать сіздер с сендер: различие — уважительность обращения.",
        "shortHint": "много людей на «вы» → -сыздар/-сіздер.",
        "decisionSteps": [
          "Несколько людей, обращение уважительное → сіздер.",
          "Твёрдое → -сыздар.",
          "Мягкое → -сіздер.",
          "Не делай существительное ещё раз множественным."
        ],
        "examples": [
          {
            "kazakh": "студентсіздер",
            "translation": "вы студенты",
            "why": "уважительно многим"
          },
          {
            "kazakh": "дәрігерсіздер",
            "translation": "вы врачи",
            "why": "тот же хвост"
          },
          {
            "kazakh": "адамсыздар",
            "translation": "вы люди",
            "why": "твёрдое сыздар"
          }
        ],
        "contrastExamples": [
          {
            "bad": "сендер на место сіздер",
            "good": "сіздер",
            "why": "Другой адресат."
          }
        ],
        "limitations": [
          "Не переносим это правило на олар."
        ],
        "commonConfusions": [
          "спутать с сендер",
          "добавить второе множественное."
        ],
