        "meaning": "Проверяем, что ученик использует біз/сендер/сіздер, прилагательные, отрицание и вопросы после р без смешения правил.",
        "fullExplanation": "Прилагательное-сказуемое получает личное окончание. У біз работают -пыз/-піз, -быз/-біз, -мыз/-міз, причём после м/н/ң нужна Б. Сендер получает -сыңдар/-сіңдер, сіздер — -сыздар/-сіздер; второе множественное на существительном в этих формах не ставится. При отрицании окончание переходит на емес: Біз кедей емеспіз, Сендер бастық емессіңдер. После форм на р вопрос получает ма/ме.",
