        "rule_id": "v2:2-3:ord",
        "title": "Порядковое: который по счёту",
        "meaning": "Количественное число отвечает «сколько?»: екі — два. Порядковое отвечает «который по счёту?»: екінші — второй.",
        "fullExplanation": "Казахское порядковое обычно строится из обычного числительного, которое уже известно из урока про числа, и специального суффикса справа. Поэтому бір остаётся основой в бірінші, а екі — в екінші. Это не множественное число и не новое слово, которое нужно учить отдельно для каждого числа. Сначала собирается обычное число, потом оно превращается в «первый/второй/…» по правилам следующих экранов.",
