        "source_item_id": "5-2.3",
        "original": "Отызыншы біріншісіңдер ме? – Отызыншы біріншісіңдер ме? – Вы тридцать первые?",
        "corrected": "Жиырмасыншысыңдар ма?",
        "reason": "Задание сборника: «Жиырманшысыңдар ма?». Печатный ключ подставляет другое предложение про тридцать первые. Ремонт строки: пропущенное сы в жиырмасыншы и сыңдар. Карточка e23-fix-8 уже хранит этот ремонт. Пакет не переписывался.",
        "status": "reviewed",
